import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BS0bAV7E.js";const O=JSON.parse('{"title":"OCIRE - OpenCubeOS 独立恢复内核","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/ocire.md","filePath":"zh/dev/ocire.md"}'),s={name:"zh/dev/ocire.md"};function n(i,e,c,l,r,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="ocire-opencubeos-独立恢复内核" tabindex="-1">OCIRE - OpenCubeOS 独立恢复内核 <a class="header-anchor" href="#ocire-opencubeos-独立恢复内核" aria-label="Permalink to &quot;OCIRE - OpenCubeOS 独立恢复内核&quot;">​</a></h1><p>状态：<strong>3.0.0-WP-01-ocire-core</strong>（本工作包交付核心：OCIRE 能独立引导并运行最小 Shell）。</p><h2 id="ocire-是什么" tabindex="-1">OCIRE 是什么 <a class="header-anchor" href="#ocire-是什么" aria-label="Permalink to &quot;OCIRE 是什么&quot;">​</a></h2><p>OCIRE 是与 Open Cube OS（OCOS）内核完全独立的第二个 L0 内核：独立源码树 （<code>ocire/</code>），不共享任何 OCOS 头文件，使用自己的链接脚本 （<code>ocire/linker_ocire.ld</code>），产出自己的引导镜像（<code>build/ocire/ocire.iso</code>）。</p><ul><li><strong>L0 = 提供服务</strong> —— OCOS 仍是全服务内核；OCIRE 是 L0 的对等体：当 OCOS 无法启动时负责恢复的内核。</li><li><strong>独立</strong> —— OCIRE 必须能够在不依赖任何 OCOS 代码、数据或分区的情况 下完成引导、运行与开关机。</li></ul><h2 id="wp-01-交付范围" tabindex="-1">WP-01 交付范围 <a class="header-anchor" href="#wp-01-交付范围" aria-label="Permalink to &quot;WP-01 交付范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>WP-01（本包）</th><th>WP-02</th><th>WP-03</th></tr></thead><tbody><tr><td>引导 + 最小 Shell</td><td><strong>本包</strong></td><td>—</td><td>—</td></tr><tr><td>help / shutdown / reboot</td><td><strong>本包</strong></td><td>—</td><td>—</td></tr><tr><td>恢复能力、FAT12、自检、修复</td><td>—</td><td>本包</td><td>—</td></tr><tr><td>启动失败检测、1 分钟超时</td><td>—</td><td>本包</td><td>—</td></tr><tr><td>OCOS&lt;-&gt;OCIRE 双向接口、进程保护</td><td>—</td><td>—</td><td>本包</td></tr></tbody></table><p>Shell 命令集固定为三条：<code>help</code>、<code>shutdown</code>、<code>reboot</code>，本包不多做。</p><h2 id="源码结构-ocire" tabindex="-1">源码结构（ocire/） <a class="header-anchor" href="#源码结构-ocire" aria-label="Permalink to &quot;源码结构（ocire/）&quot;">​</a></h2><p>见 <code>docs/dev/ocire.md</code>（英文版，与本镜像内容一致）的源码布局、构建目标 与源文件说明。编译使用与 OCOS 内核相同的 <code>-Wall -Wextra -Werror</code> 零警告门，CI 在每次 push 上编译 OCIRE。</p><h2 id="双系统磁盘布局与分区隔离" tabindex="-1">双系统磁盘布局与分区隔离 <a class="header-anchor" href="#双系统磁盘布局与分区隔离" aria-label="Permalink to &quot;双系统磁盘布局与分区隔离&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hd0（ocire-boot.img，tools/make_ocire_disk.sh 生成）</span></span>
<span class="line"><span>  GRUB 双菜单（BIOS：MBR + post-MBR gap；UEFI：FAT 分区上的</span></span>
<span class="line"><span>  /EFI/BOOT/BOOTX64.EFI）</span></span>
<span class="line"><span>  -&gt; 菜单第 1 项（默认）引导 OCOS</span></span>
<span class="line"><span>  -&gt; 菜单第 2 项引导 OCIRE</span></span>
<span class="line"><span></span></span>
<span class="line"><span>hd1（ocire-hd.img）—— OCIRE 独立盘</span></span>
<span class="line"><span>  MBR 仅一个条目，type 0xEE（&quot;GPT 保护阴影条目&quot;），其后没有 GPT 头；</span></span>
<span class="line"><span>  OCIRE 内核镜像以原始形式存放在分区起点（LBA 2048）。</span></span>
<span class="line"><span>  -&gt; GRUB 菜单用整盘 blocklist 加载：multiboot2 (hd1)2048+128</span></span>
<span class="line"><span>  -&gt; OCOS 侧：0xEE 使其分区解析器切换到 GPT 模式，没有 GPT 头则</span></span>
<span class="line"><span>     解析失败 -&gt; 整表拒绝 -&gt; OCIRE 分区在 OCOS 里没有任何设备节点</span></span>
<span class="line"><span>     与文件系统路径。</span></span></code></pre></div><p>实测证据：<code>evidence/3_0_0_wp01_ocire/isolation.log</code>（在 OCOS 内运行：</p><ul><li><code>partscan: 1 partition device(s) registered</code>（OCIRE 盘贡献 0 个子设备）</li><li><code>parted hda</code> → <code>no partition table found</code></li><li><code>mkfs.fat32 hdap1 confirm</code> → <code>device not found</code>（无写入路径）</li><li><code>disk_rw_test hdap1</code> → <code>device lookup FAIL</code>（无读取路径）</li><li><code>df</code> → 只挂载 OCOS 自己的卷</li></ul><p>诚实边界（同样实测，<code>isolation_rawdecl.log</code>）：整盘设备节点仍然存在， <code>disk_rw_test hda</code> 与 <code>mkfs.fat32 hda confirm</code> 在一次性副本上均可执行， 与 Linux root 对 <code>/dev/sdb</code> 的语义相同。阻止管理员级整盘操作需要修改 OCOS 块层策略——本包被明确禁止修改 OCOS——该硬化归 WP-03（进程保护）。</p><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><ul><li><code>make ocire-test</code> —— 14 例（BIOS+UEFI：引导到 Shell、help、未知命令 提示、退格编辑、shutdown 真关机、reboot 真重启）。</li><li><code>make ocire-dual-test</code> —— 11 例（四组双引导组合 + 五项隔离探测 + 两项整盘边界申报）。</li><li>OCOS 全回归矩阵在&quot;含 OCIRE、零 OCOS 改动&quot;的树上重跑： <code>evidence/3_0_0_wp01_ocire/regression/</code>（host tests、可复现构建、 wp12、wp10_tui、chinese、tuiqa 双固件、native 双固件、l1_per_app、 wait4 fresh-boot 电池 20/20、boot gates）全部与 2.2.0 发布基线一致。</li></ul>`,17)])])}const u=t(s,[["render",n]]);export{O as __pageData,u as default};
